    "검토·심사": "Revisión y envío",
    "에셋 정보를 먼저 임시저장한 뒤 파일을 올려주세요. 파일당 최대 300MB이며, 원본은 공개되지 않습니다.": "Guarda el borrador antes de subir archivos. El límite es 300MB por archivo. Los originales no son públicos.",
    "영문 제목·설명, 납품 항목, 원본과 미리보기 파일이 필요합니다. 제출 후 심사를 거쳐 판매가 시작됩니다.": "Se requieren título y descripción en inglés, entregables, originales y vista previa. La venta empieza tras el envío y la aprobación.",
    "독점 판매는 한 구매자에게만 제공됩니다. 여러 사람에게 판매는 구매자마다 이용 권한을 제공하며, 재판매 허용 여부는 납품 항목에 적어주세요.": "Los recursos exclusivos se ofrecen a un solo comprador. Los no exclusivos conceden licencias por comprador. Indica en los entregables cualquier permiso de reventa.",
    "해당 계약(v1)을 확인했고, 기재한 제외·제한 사항을 포함하여 판매 조건으로 적용하는 데 동의합니다.": "He revisado el contrato v1 y acepto aplicarlo a la venta, incluidas las exclusiones y limitaciones indicadas.",
    "상업적 이용 허용 및 수정에 동의합니다.": "Permito el uso comercial y las modificaciones.",
    "위 이용 권한을 허락할 정당한 권한이 있으며, 제3자 권리 및 제한 사항을 에셋 설명에 정확히 고지했음을 확인합니다.": "Confirmo que puedo conceder estos permisos y que he descrito con precisión los derechos y limitaciones de terceros en la descripción.",
    "상업적 이용과 수정을 허용할 경우 아래 항목에 동의해주세요. 재배포·재판매는 이 동의에 포함되지 않으며 별도 합의가 필요합니다. 제3자 소재와 사용 도구의 약관이 허용하는 범위 안에서만 권한을 설정할 수 있습니다.": "Confirma abajo si permites el uso comercial y las modificaciones. Redistribuir y revender requiere acuerdo separado. Los permisos deben respetar los derechos de terceros y los términos de las herramientas.",
    "등록된 가격 가이드가 없습니다. 최종 판매가는 직접 입력해주세요.": "No hay guía de precios. Introduce tu precio final.",
    "가격 가이드를 불러오지 못했습니다. 판매가는 직접 입력할 수 있습니다.": "No se pudo cargar la guía de precios. Puedes introducir tu precio.",
    "입력은 이 기기의 브라우저에 자동 저장됩니다. 7일 이내 초안을 복원할 수 있으며 파일은 자동 업로드하지 않습니다.": "Los datos se guardan automáticamente en este navegador durante siete días. Los archivos no se suben automáticamente.",
    "이 기기의 브라우저에 자동 저장했습니다. 서버 저장은 아래 임시저장을 눌러주세요. (7일 이내 초안 복원 가능)": "Guardado en este navegador. Usa Guardar borrador para guardar en el servidor. Se puede restaurar durante siete días.",
    "브라우저에 저장 중…": "Guardando en este navegador…",
    "브라우저 자동 저장을 사용할 수 없습니다. 임시저장 버튼으로 서버에 저장해주세요.": "El guardado automático no está disponible. Usa Guardar borrador para guardar en el servidor.",
    "이 기기에 저장된 작성 내용이 있습니다. 복원하면 현재 입력을 대체합니다. 계약·권리 확인은 다시 선택해주세요.": "Hay un borrador en este dispositivo. Restaurarlo sustituye las entradas actuales. Confirma de nuevo el contrato y los derechos.",
    "작성 내용을 복원했습니다. 계약·권리 확인 후 서버에 임시저장해주세요.": "Borrador restaurado. Revisa el contrato y los derechos y guarda en el servidor.",
    "브라우저 초안을 삭제했습니다. 서버의 저장 내용은 유지됩니다.": "Borrador del navegador descartado. Los datos del servidor se conservan.",
    "브라우저 초안을 삭제하지 못했습니다.": "No se pudo descartar el borrador del navegador.",
    "로그인이 필요해요.": "Inicia sesión.",
    "로그인이 필요합니다.": "Inicia sesión.",
