    "관리자 권한이 필요해요.": "Se requiere acceso de administrador.",
    "요청 출처를 확인해주세요.": "No se pudo verificar el origen de la solicitud.",
    "입력값을 확인해주세요.": "Comprueba los datos introducidos.",
    "요청이 너무 커요.": "La solicitud es demasiado grande.",
    "지원하지 않는 요청입니다.": "Esta solicitud no está admitida.",
    "연결에 실패했어요.": "La conexión falló.",
    "잠시 후 다시 시도해주세요.": "Inténtalo más tarde.",
    "카테고리와 양의 정수 가격 범위를 확인해주세요.": "Comprueba la categoría y el rango de precios en enteros positivos.",
    "수정 요청·거절에는 처리 사유(1~1000자)가 필요합니다.": "Para solicitar cambios o rechazar se requiere un motivo de 1 a 1.000 caracteres.",
    "비회원 찜은 로그인 후 이용할 수 있어요.": "Inicia sesión para guardar favoritos.",
    "로그인 후 찜할 수 있어요.": "Inicia sesión para guardar favoritos.",
    "홈 화면 시안 · 영상 카드는 작업 폴더의 perfume1과 NovaNoxX 모션 로고를 사용한 재생 샘플입니다. 다른 에셋 이미지와 가격은 예시입니다. 실제 결제와 판매는 진행되지 않습니다.": "Vista previa del sitio. Las tarjetas de vídeo usan perfume1 y el logotipo animado de NovaNoxX como ejemplos. Las demás imágenes y precios son ilustrativos. No hay pagos ni ventas reales.",
    "현재 결제와 구매는 TEST 단계입니다. 격리 환경의 구현·검증은 실제 결제·납품·판매자 지급 완료를 뜻하지 않습니다.": "Los pagos y compras están en modo TEST. La implementación y las comprobaciones aisladas no implican pagos, entregas ni cobros de vendedores reales.",
    "계약 원문은 한국어입니다. 아래 계약 조건을 확인해주세요.": "El contrato original está en coreano. Consulta el contrato de abajo.",
    "정책 원문은 한국어입니다. 아래 정책을 확인해주세요.": "La política original está en coreano. Consulta la política de abajo.",
