    "검토·심사": "检查与提交",
    "에셋 정보를 먼저 임시저장한 뒤 파일을 올려주세요. 파일당 최대 300MB이며, 원본은 공개되지 않습니다.": "上传文件前请先保存草稿。每个文件上限300MB，原始文件不公开。",
    "영문 제목·설명, 납품 항목, 원본과 미리보기 파일이 필요합니다. 제출 후 심사를 거쳐 판매가 시작됩니다.": "必须提供英文标题与说明、交付内容、原始文件和预览文件。提交并审核通过后开始销售。",
    "독점 판매는 한 구매자에게만 제공됩니다. 여러 사람에게 판매는 구매자마다 이용 권한을 제공하며, 재판매 허용 여부는 납품 항목에 적어주세요.": "独家资源仅提供给一位买家，非独家资源向每位买家分别授权。若允许转售，请在交付内容中说明。",
    "해당 계약(v1)을 확인했고, 기재한 제외·제한 사항을 포함하여 판매 조건으로 적용하는 데 동의합니다.": "我已阅读协议v1，并同意将其连同所述排除和限制条款适用于本次销售。",
    "상업적 이용 허용 및 수정에 동의합니다.": "我允许商业使用与修改。",
    "위 이용 권한을 허락할 정당한 권한이 있으며, 제3자 권리 및 제한 사항을 에셋 설명에 정확히 고지했음을 확인합니다.": "我确认有权授予这些权限，并已在资源说明中如实披露第三方权利和限制。",
    "상업적 이용과 수정을 허용할 경우 아래 항목에 동의해주세요. 재배포·재판매는 이 동의에 포함되지 않으며 별도 합의가 필요합니다. 제3자 소재와 사용 도구의 약관이 허용하는 범위 안에서만 권한을 설정할 수 있습니다.": "如允许商业使用与修改，请在下方确认。再分发与转售需另行约定。授权不得超出第三方权利或工具条款。",
    "등록된 가격 가이드가 없습니다. 최종 판매가는 직접 입력해주세요.": "尚未设置价格参考，请自行输入最终售价。",
    "가격 가이드를 불러오지 못했습니다. 판매가는 직접 입력할 수 있습니다.": "无法加载价格参考，仍可自行输入售价。",
    "입력은 이 기기의 브라우저에 자동 저장됩니다. 7일 이내 초안을 복원할 수 있으며 파일은 자동 업로드하지 않습니다.": "输入内容自动保存在此浏览器，七天内可恢复。文件不会自动上传。",
    "이 기기의 브라우저에 자동 저장했습니다. 서버 저장은 아래 임시저장을 눌러주세요. (7일 이내 초안 복원 가능)": "已保存在此浏览器。使用“保存资源草稿”可保存到服务器。浏览器草稿七天内可恢复。",
    "브라우저에 저장 중…": "正在此浏览器中保存…",
    "브라우저 자동 저장을 사용할 수 없습니다. 임시저장 버튼으로 서버에 저장해주세요.": "浏览器自动保存不可用，请使用“保存资源草稿”保存到服务器。",
    "이 기기에 저장된 작성 내용이 있습니다. 복원하면 현재 입력을 대체합니다. 계약·권리 확인은 다시 선택해주세요.": "此设备上已有草稿。恢复将替换当前输入，请重新确认协议与权利。",
    "작성 내용을 복원했습니다. 계약·권리 확인 후 서버에 임시저장해주세요.": "草稿已恢复。请检查协议和权利，再保存到服务器。",
    "브라우저 초안을 삭제했습니다. 서버의 저장 내용은 유지됩니다.": "浏览器草稿已丢弃，服务器数据保留。",
    "브라우저 초안을 삭제하지 못했습니다.": "无法丢弃浏览器草稿。",
