    "카테고리와 양의 정수 가격 범위를 확인해주세요.": "请检查分类以及正整数价格范围。",
    "수정 요청·거절에는 처리 사유(1~1000자)가 필요합니다.": "要求修改或拒绝时需填写1至1000个字符的原因。",
    "비회원 찜은 로그인 후 이용할 수 있어요.": "登录后即可收藏资源。",
    "로그인 후 찜할 수 있어요.": "登录后即可收藏资源。",
    "홈 화면 시안 · 영상 카드는 작업 폴더의 perfume1과 NovaNoxX 모션 로고를 사용한 재생 샘플입니다. 다른 에셋 이미지와 가격은 예시입니다. 실제 결제와 판매는 진행되지 않습니다.": "主页预览。视频卡片使用perfume1片段和NovaNoxX动态标志作为示例，其他图片和价格也为示例。不会发生真实支付或销售。",
    "현재 결제와 구매는 TEST 단계입니다. 격리 환경의 구현·검증은 실제 결제·납품·판매자 지급 완료를 뜻하지 않습니다.": "当前支付和购买处于TEST模式。隔离实现和检查不代表已发生真实支付、交付或卖家收款。",
