"진행 중 주문은 검토 동안 보류됩니다. 환불·정산·권리 이전은 실행하지 않습니다.":"Đơn đang xử lý được tạm giữ khi xem xét. Không thực hiện hoàn tiền, quyết toán hay chuyển quyền.",
