"TEST 기록의 연결만 조회합니다. 운영 거래 생성·잔액 이전·원본 권한 부여는 하지 않습니다. 기존 원본 지문은 선택한 파일만 읽어 등록합니다.":"Chỉ xem kết nối hồ sơ TEST. Không tạo giao dịch thật, chuyển số dư hay cấp quyền. Chỉ đọc tệp gốc đã chọn để ghi dấu vân tay.",
