    "번역 중인 일부 화면은 영어로 표시됩니다. 계약은 한국어 원문과 영문 참고 번역으로 제공되며 창작자 콘텐츠는 원문으로 표시됩니다.": "Một số trang đang được dịch và có thể hiển thị bằng tiếng Anh. Hợp đồng có bản gốc tiếng Hàn và bản dịch tiếng Anh để tham khảo. Nội dung của nhà sáng tạo được giữ nguyên ngôn ngữ gốc.",
