    "검토·심사": "Kiểm tra và gửi",
    "에셋 정보를 먼저 임시저장한 뒤 파일을 올려주세요. 파일당 최대 300MB이며, 원본은 공개되지 않습니다.": "Lưu bản nháp trước khi tải tệp. Giới hạn 300MB mỗi tệp. Tệp gốc không công khai.",
    "영문 제목·설명, 납품 항목, 원본과 미리보기 파일이 필요합니다. 제출 후 심사를 거쳐 판매가 시작됩니다.": "Cần tiêu đề và mô tả tiếng Anh, hạng mục bàn giao, tệp gốc và xem trước. Bắt đầu bán sau khi gửi và được duyệt.",
    "독점 판매는 한 구매자에게만 제공됩니다. 여러 사람에게 판매는 구매자마다 이용 권한을 제공하며, 재판매 허용 여부는 납품 항목에 적어주세요.": "Tài nguyên độc quyền dành cho một người mua. Tài nguyên không độc quyền cấp phép riêng cho từng người. Nêu rõ quyền bán lại trong hạng mục bàn giao.",
    "해당 계약(v1)을 확인했고, 기재한 제외·제한 사항을 포함하여 판매 조건으로 적용하는 데 동의합니다.": "Tôi đã xem hợp đồng v1 và đồng ý áp dụng cho giao dịch, bao gồm các loại trừ và hạn chế đã nêu.",
    "상업적 이용 허용 및 수정에 동의합니다.": "Tôi cho phép sử dụng thương mại và chỉnh sửa.",
    "위 이용 권한을 허락할 정당한 권한이 있으며, 제3자 권리 및 제한 사항을 에셋 설명에 정확히 고지했음을 확인합니다.": "Tôi xác nhận có quyền cấp các quyền này và đã công bố chính xác quyền cùng hạn chế của bên thứ ba trong mô tả.",
    "상업적 이용과 수정을 허용할 경우 아래 항목에 동의해주세요. 재배포·재판매는 이 동의에 포함되지 않으며 별도 합의가 필요합니다. 제3자 소재와 사용 도구의 약관이 허용하는 범위 안에서만 권한을 설정할 수 있습니다.": "Xác nhận bên dưới nếu cho phép sử dụng thương mại và chỉnh sửa. Phân phối hoặc bán lại cần thỏa thuận riêng. Quyền cấp phải phù hợp quyền bên thứ ba và điều khoản công cụ.",
    "등록된 가격 가이드가 없습니다. 최종 판매가는 직접 입력해주세요.": "Chưa có hướng dẫn giá. Hãy tự nhập giá cuối cùng.",
    "가격 가이드를 불러오지 못했습니다. 판매가는 직접 입력할 수 있습니다.": "Không tải được hướng dẫn giá. Bạn vẫn có thể nhập giá riêng.",
    "입력은 이 기기의 브라우저에 자동 저장됩니다. 7일 이내 초안을 복원할 수 있으며 파일은 자동 업로드하지 않습니다.": "Dữ liệu tự lưu trong trình duyệt và có thể khôi phục trong bảy ngày. Tệp không tự tải lên.",
    "이 기기의 브라우저에 자동 저장했습니다. 서버 저장은 아래 임시저장을 눌러주세요. (7일 이내 초안 복원 가능)": "Đã lưu trong trình duyệt. Dùng Lưu bản nháp tài nguyên để lưu lên máy chủ. Có thể khôi phục trong bảy ngày.",
    "브라우저에 저장 중…": "Đang lưu trong trình duyệt…",
    "브라우저 자동 저장을 사용할 수 없습니다. 임시저장 버튼으로 서버에 저장해주세요.": "Không thể tự lưu trong trình duyệt. Hãy dùng Lưu bản nháp tài nguyên để lưu lên máy chủ.",
    "이 기기에 저장된 작성 내용이 있습니다. 복원하면 현재 입력을 대체합니다. 계약·권리 확인은 다시 선택해주세요.": "Thiết bị có bản nháp. Khôi phục sẽ thay thế dữ liệu hiện tại. Hãy xác nhận lại hợp đồng và quyền sử dụng.",
    "작성 내용을 복원했습니다. 계약·권리 확인 후 서버에 임시저장해주세요.": "Đã khôi phục bản nháp. Kiểm tra hợp đồng, quyền và lưu lên máy chủ.",
    "브라우저 초안을 삭제했습니다. 서버의 저장 내용은 유지됩니다.": "Đã bỏ bản nháp trình duyệt. Dữ liệu máy chủ được giữ lại.",
    "브라우저 초안을 삭제하지 못했습니다.": "Không thể bỏ bản nháp trình duyệt.",
    "로그인이 필요해요.": "Vui lòng đăng nhập.",
    "로그인이 필요합니다.": "Vui lòng đăng nhập.",
    "관리자 권한이 필요합니다.": "Cần quyền quản trị.",
    "관리자 권한이 필요해요.": "Cần quyền quản trị.",
    "요청 출처를 확인해주세요.": "Không xác minh được nguồn yêu cầu.",
    "입력값을 확인해주세요.": "Vui lòng kiểm tra dữ liệu đã nhập.",
    "요청이 너무 커요.": "Yêu cầu quá lớn.",
    "지원하지 않는 요청입니다.": "Không hỗ trợ yêu cầu này.",
    "연결에 실패했어요.": "Kết nối thất bại.",
    "잠시 후 다시 시도해주세요.": "Vui lòng thử lại sau.",
    "카테고리와 양의 정수 가격 범위를 확인해주세요.": "Kiểm tra danh mục và khoảng giá là số nguyên dương.",
    "수정 요청·거절에는 처리 사유(1~1000자)가 필요합니다.": "Yêu cầu sửa hoặc từ chối cần lý do dài từ 1 đến 1.000 ký tự.",
    "비회원 찜은 로그인 후 이용할 수 있어요.": "Đăng nhập để lưu tài nguyên yêu thích.",
    "로그인 후 찜할 수 있어요.": "Đăng nhập để lưu tài nguyên yêu thích.",
    "홈 화면 시안 · 영상 카드는 작업 폴더의 perfume1과 NovaNoxX 모션 로고를 사용한 재생 샘플입니다. 다른 에셋 이미지와 가격은 예시입니다. 실제 결제와 판매는 진행되지 않습니다.": "Bản xem trước trang chủ. Thẻ video dùng đoạn perfume1 và logo chuyển động NovaNoxX làm mẫu. Hình và giá khác là ví dụ. Không có thanh toán hay bán hàng thật.",
