    "구매 전에는 워터마크가 있는 Preview로 에셋을 확인하세요. 거래가 완료되면 약속된 최종 납품파일을 받을 수 있습니다.": "Xem bản có dấu bản quyền trước khi mua. Tệp cuối đã thỏa thuận được cung cấp sau khi hoàn tất giao dịch.",
    "글로벌 크리에이터 네트워크": "Mạng lưới nhà sáng tạo toàn cầu",
    "다양한 크리에이터의 에셋을 한곳에서 만나보세요. 원하는 완성된 에셋이 없다면 제작 의뢰를 남기고 제안을 비교할 수 있습니다.": "Khám phá tác phẩm của nhiều nhà sáng tạo tại một nơi. Nếu chưa phù hợp, chuẩn bị yêu cầu để so sánh đề xuất khi khả dụng.",
    "보기": "Xem",
    "기존 계정에 카카오를 연결하세요.": "Liên kết Kakao với tài khoản hiện có.",
    "① 아래에서 처음 가입한 방식으로 로그인해주세요.": "1. Đăng nhập bằng phương thức đăng ký ban đầu.",
    "② 로그인 후 나타나는 카카오 연결 버튼을 눌러주세요.": "2. Sau đăng nhập, chọn Liên kết Kakao.",
    "③ 연결하면 두 로그인 방식으로 같은 계정을 이용할 수 있어요.": "3. Dùng một trong hai cách đăng nhập cho cùng tài khoản.",
