    "실제 거래 연동 전입니다. 아래 기록은 TEST 거래이며 실제 결제·정산이 아닙니다.": "Echter Handel ist nicht angebunden. Dies sind TEST-Transaktionen, keine echten Zahlungen oder Auszahlungen.",
    "조회 전용입니다. 회원 권한·잔액·결제 상태는 여기에서 변경하지 않습니다.": "Nur zur Ansicht. Mitgliedszugang, Guthaben und Zahlungsstatus können hier nicht geändert werden.",
