    "추가 작업": "Anpassung",
    "검토·심사": "Prüfen und einreichen",
    "에셋 정보를 먼저 임시저장한 뒤 파일을 올려주세요. 파일당 최대 300MB이며, 원본은 공개되지 않습니다.": "Speichere den Entwurf vor dem Hochladen. Die Grenze beträgt 300MB je Datei. Originale sind nicht öffentlich.",
    "영문 제목·설명, 납품 항목, 원본과 미리보기 파일이 필요합니다. 제출 후 심사를 거쳐 판매가 시작됩니다.": "Englischer Titel und Beschreibung, Lieferumfang, Originale und Vorschau sind erforderlich. Der Verkauf beginnt nach Einreichung und Genehmigung.",
    "독점 판매는 한 구매자에게만 제공됩니다. 여러 사람에게 판매는 구매자마다 이용 권한을 제공하며, 재판매 허용 여부는 납품 항목에 적어주세요.": "Exklusive Assets werden einem Käufer bereitgestellt. Nicht exklusive Assets werden je Käufer lizenziert. Gib eine etwaige Wiederverkaufserlaubnis im Lieferumfang an.",
    "해당 계약(v1)을 확인했고, 기재한 제외·제한 사항을 포함하여 판매 조건으로 적용하는 데 동의합니다.": "Ich habe Vertrag v1 geprüft und stimme seiner Anwendung auf den Verkauf einschließlich der genannten Ausschlüsse und Einschränkungen zu.",
    "상업적 이용 허용 및 수정에 동의합니다.": "Ich erlaube kommerzielle Nutzung und Bearbeitung.",
    "위 이용 권한을 허락할 정당한 권한이 있으며, 제3자 권리 및 제한 사항을 에셋 설명에 정확히 고지했음을 확인합니다.": "Ich bestätige, diese Rechte gewähren zu dürfen und Rechte sowie Einschränkungen Dritter in der Beschreibung korrekt offengelegt zu haben.",
    "상업적 이용과 수정을 허용할 경우 아래 항목에 동의해주세요. 재배포·재판매는 이 동의에 포함되지 않으며 별도 합의가 필요합니다. 제3자 소재와 사용 도구의 약관이 허용하는 범위 안에서만 권한을 설정할 수 있습니다.": "Bestätige unten kommerzielle Nutzung und Bearbeitung. Weiterverbreitung und Weiterverkauf erfordern eine gesonderte Vereinbarung. Rechte Dritter und Werkzeugbedingungen gelten weiterhin.",
    "등록된 가격 가이드가 없습니다. 최종 판매가는 직접 입력해주세요.": "Keine Preisrichtlinie hinterlegt. Gib deinen Endpreis ein.",
    "가격 가이드를 불러오지 못했습니다. 판매가는 직접 입력할 수 있습니다.": "Die Preisrichtlinie konnte nicht geladen werden. Du kannst deinen Preis trotzdem eingeben.",
    "입력은 이 기기의 브라우저에 자동 저장됩니다. 7일 이내 초안을 복원할 수 있으며 파일은 자동 업로드하지 않습니다.": "Eingaben werden in diesem Browser automatisch gespeichert und können sieben Tage lang wiederhergestellt werden. Dateien werden nicht automatisch hochgeladen.",
    "이 기기의 브라우저에 자동 저장했습니다. 서버 저장은 아래 임시저장을 눌러주세요. (7일 이내 초안 복원 가능)": "In diesem Browser gespeichert. Mit Asset-Entwurf speichern wird auf dem Server gespeichert. Browserentwürfe sind sieben Tage wiederherstellbar.",
    "브라우저에 저장 중…": "Wird in diesem Browser gespeichert…",
    "브라우저 자동 저장을 사용할 수 없습니다. 임시저장 버튼으로 서버에 저장해주세요.": "Automatisches Speichern im Browser ist nicht verfügbar. Nutze Asset-Entwurf speichern für den Server.",
    "이 기기에 저장된 작성 내용이 있습니다. 복원하면 현재 입력을 대체합니다. 계약·권리 확인은 다시 선택해주세요.": "Auf diesem Gerät liegt ein Entwurf vor. Die Wiederherstellung ersetzt aktuelle Eingaben. Bestätige Vertrag und Rechte erneut.",
    "작성 내용을 복원했습니다. 계약·권리 확인 후 서버에 임시저장해주세요.": "Entwurf wiederhergestellt. Prüfe Vertrag und Rechte und speichere auf dem Server.",
    "브라우저 초안을 삭제했습니다. 서버의 저장 내용은 유지됩니다.": "Browserentwurf verworfen. Serverdaten bleiben erhalten.",
    "브라우저 초안을 삭제하지 못했습니다.": "Browserentwurf konnte nicht verworfen werden.",
    "로그인이 필요해요.": "Bitte melde dich an.",
    "로그인이 필요합니다.": "Bitte melde dich an.",
    "관리자 권한이 필요합니다.": "Administratorzugriff erforderlich.",
    "관리자 권한이 필요해요.": "Administratorzugriff erforderlich.",
    "요청 출처를 확인해주세요.": "Die Herkunft der Anfrage konnte nicht geprüft werden.",
    "입력값을 확인해주세요.": "Bitte prüfe deine Eingaben.",
    "요청이 너무 커요.": "Die Anfrage ist zu groß.",
    "지원하지 않는 요청입니다.": "Diese Anfrage wird nicht unterstützt.",
    "연결에 실패했어요.": "Verbindung fehlgeschlagen.",
    "잠시 후 다시 시도해주세요.": "Bitte versuche es später erneut.",
    "카테고리와 양의 정수 가격 범위를 확인해주세요.": "Prüfe Kategorie und Preisbereich aus positiven ganzen Zahlen.",
    "수정 요청·거절에는 처리 사유(1~1000자)가 필요합니다.": "Änderungswünsche und Ablehnungen erfordern eine Begründung mit 1 bis 1.000 Zeichen.",
    "비회원 찜은 로그인 후 이용할 수 있어요.": "Melde dich an, um Assets zu merken.",
    "로그인 후 찜할 수 있어요.": "Melde dich an, um Assets zu merken.",
    "홈 화면 시안 · 영상 카드는 작업 폴더의 perfume1과 NovaNoxX 모션 로고를 사용한 재생 샘플입니다. 다른 에셋 이미지와 가격은 예시입니다. 실제 결제와 판매는 진행되지 않습니다.": "Homepage-Vorschau. Videokarten nutzen perfume1 und das bewegte NovaNoxX-Logo als Beispiele. Andere Bilder und Preise sind Beispiele. Es finden keine echten Zahlungen oder Verkäufe statt.",
    "현재 결제와 구매는 TEST 단계입니다. 격리 환경의 구현·검증은 실제 결제·납품·판매자 지급 완료를 뜻하지 않습니다.": "Zahlungen und Käufe befinden sich im TEST-Modus. Isolierte Implementierung und Prüfungen bedeuten keine echten Zahlungen, Lieferungen oder Verkäuferauszahlungen.",
    "계약 원문은 한국어입니다. 아래 계약 조건을 확인해주세요.": "Der Originalvertrag ist auf Koreanisch. Lies den Vertrag unten.",
    "정책 원문은 한국어입니다. 아래 정책을 확인해주세요.": "Die Originalrichtlinie ist auf Koreanisch. Lies die Richtlinie unten.",
