    "없다면, 함께 만드세요.": "Gemeinsam gestalten.",
    "원하는 크리에이티브와 예산, 일정을 알려주세요. 크리에이터의 제안을 비교하는 출발점입니다.": "Teile dein Briefing, Budget und deinen Zeitplan, um Angebote zu vergleichen.",
