    "뜻밖의 발견이, 다음 가능성으로.": "Eine unerwartete Entdeckung. Eine neue Möglichkeit.",
    "크리에이티브와 AI 도구를 발견하고, 당신의 브랜드와 작업으로 연결하세요.": "Entdecke kreative Assets und KI-Werkzeuge für deine Marke und dein nächstes Projekt.",
    "궁금한 점을 확인하세요.": "Finde Antworten auf deine Fragen.",
    "서비스 이용부터 에셋 등록, NEON과 라이선스까지.": "Dienstnutzung, Asset-Registrierung, NEON und Lizenzen.",
    "새로운 감각. 당신의 출품작으로.": "Eine neue Perspektive. Dein kreativer Beitrag.",
    "AI로 확장한 상상력, 나만의 시선을 담은 출품작을 만나보세요.": "Entdecke Beiträge mit einzigartigen Perspektiven und KI-gestützter Vorstellungskraft.",
    "당신의 출품작을 보여주세요.": "Zeige deinen kreativen Beitrag.",
    "제출한 미리보기는 콘테스트 페이지에 공개됩니다. 원본 납품 파일 대신 공개용 파일을 올려주세요.": "Die Vorschau ist auf der Wettbewerbsseite öffentlich. Lade eine öffentliche Vorschau statt der Original-Lieferdatei hoch.",
