    "공개 파일 보호": "Schutz öffentlicher Dateien",
    "기존 파일은 보존하고 보호 사본을 만듭니다. 보호 확인 전에는 공개 파일이 제공되지 않습니다.": "Bestehende Dateien bleiben erhalten und geschützte Kopien werden erstellt. Öffentliche Dateien sind erst nach Schutzprüfung verfügbar.",
