    "거래 수수료 12% (PG·수수료 부가세 포함)": "12% Gesamtverkaufsgebühr (einschließlich Zahlungsabwicklung und Umsatzsteuer auf die Gebühr)",
    "신규 크리에이터에게 PLUS 14일 무료 체험을 제공합니다. SOLD 에셋은 판매 중 에셋 한도에서 제외됩니다.": "Neue Kreative erhalten einen 14-tägigen PLUS-Test. SOLD-Assets zählen nicht zum Limit aktiver Angebote.",
    "요금제 안내 시안입니다. 가입과 구독 결제는 아직 연결되지 않았습니다.": "Tarifvorschau. Anmeldung und Abozahlungen sind noch nicht angebunden.",
    "연결하면 카카오로도 지금 로그인한 계정을 이용할 수 있어요. 아래 버튼을 눌러 카카오에서 본인 인증을 완료해주세요.": "Verknüpfe Kakao mit deinem aktuellen Konto. Bestätige deine Identität über Kakao mit der Schaltfläche unten.",
