    "크리에이티브.": "Kreative Arbeit.",
    "브랜드 적용이 가능한 에셋": "Assets bereit für deine Marke",
    "마음에 드는 완성된 에셋에 로고, 브랜드명, 카피, 색상을 더해 당신의 브랜드로 완성하세요. 적용 가능한 항목은 에셋마다 확인할 수 있습니다.": "Ergänze Logo, Markenname, Text und Farben bei unterstützten Assets. Prüfe die verfügbaren Optionen im jeweiligen Angebot.",
    "한 구매자만을 위한 에셋": "Ein exklusives Asset für einen Käufer",
    "하나의 에셋은 단 한 번만 판매됩니다. 거래가 완료되면 판매가 종료되고, 에셋 페이지에는 SOLD가 표시됩니다.": "Ein exklusives Asset wird einmal verkauft. Nach Abschluss endet der Verkauf und die Seite zeigt SOLD.",
    "구매 전에는 워터마크가 있는 Preview로 에셋을 확인하세요. 거래가 완료되면 약속된 최종 납품파일을 받을 수 있습니다.": "Prüfe vor dem Kauf die Vorschau mit Wasserzeichen. Vereinbarte finale Dateien folgen nach Transaktionsabschluss.",
    "글로벌 크리에이터 네트워크": "Ein globales Kreativnetzwerk",
    "다양한 크리에이터의 에셋을 한곳에서 만나보세요. 원하는 완성된 에셋이 없다면 제작 의뢰를 남기고 제안을 비교할 수 있습니다.": "Entdecke Arbeiten verschiedener Kreativer an einem Ort. Passt kein Asset, bereite einen Auftrag vor, um bei Verfügbarkeit Angebote zu vergleichen.",
    "보기": "Ansehen",
    "기존 계정에 카카오를 연결하세요.": "Verknüpfe Kakao mit deinem bestehenden Konto.",
    "① 아래에서 처음 가입한 방식으로 로그인해주세요.": "1. Melde dich mit deiner ursprünglichen Registrierungsmethode an.",
    "② 로그인 후 나타나는 카카오 연결 버튼을 눌러주세요.": "2. Wähle nach der Anmeldung Kakao verknüpfen.",
    "③ 연결하면 두 로그인 방식으로 같은 계정을 이용할 수 있어요.": "3. Nutze beide Anmeldemethoden für dasselbe Konto.",
    "크리에이터 안내로 돌아가기": "Zurück zu Kreativinformationen",
    "내 컴퓨터의 에셋 파일로 첫 에셋을 등록해보세요.": "Registriere dein erstes Asset mit Dateien von deinem Computer.",
    "에셋을 찾을 수 없어요.": "Asset nicht gefunden.",
    "로고·브랜드명·카피·색상 적용은 지원 항목에 한해 기본가에 포함됩니다.": "Logo-, Markennamen-, Text- und Farbänderungen sind nur enthalten, soweit das Angebot sie unterstützt.",
    "진행 중 · 검수 대기 · 완료 주문을 이곳에서 관리합니다.": "Verwalte hier laufende Bestellungen, Lieferprüfungen und abgeschlossene Bestellungen.",
    "결제 연동 후 주문 상세, 자료 제출 확인, 메시지·파일 전달과 납품 검수가 연결됩니다.": "Bestelldetails, Materialien, Nachrichten, Dateien und Lieferprüfung werden mit der Zahlungsintegration angebunden.",
    "의뢰가 등록되면 제작 방향·가격·기간·수정 조건을 담아 제안할 수 있습니다.": "Nach Veröffentlichung von Aufträgen können Angebote Richtung, Preis, Zeitplan und Änderungsbedingungen angeben.",
    "제작 의뢰 화면 보기 ↗": "Aufträge ansehen ↗",
    "정산 내역에는 판매금액, 총 수수료 12% (PG 결제수수료·수수료 부가세 포함), 실수령액과 지급 상태가 표시됩니다.": "Auszahlungsdaten zeigen Verkaufspreis, 12% Gesamtgebühr einschließlich Abwicklung und Gebühren-Umsatzsteuer, Nettobetrag und Zahlungsstatus.",
