    "플랜 안내": "Tarifinformationen",
    "현재는 에셋 임시저장과 심사 제출을 이용할 수 있습니다. 유료 구독은 아직 시작되지 않으며 결제도 발생하지 않습니다.": "Du kannst derzeit Entwürfe speichern und zur Prüfung einreichen. Bezahlabos sind nicht gestartet und es fallen keine Aboabbuchungen an.",
