    "업로드 또는 영상 구간 생성에 실패했습니다. 파일은 300MB 이하이며, 영상은 선택한 구간이 실제 길이 안에 있어야 합니다. 저장 공간이 부족하면 관리자에게 문의해주세요.": "Upload oder Vorschaukonvertierung fehlgeschlagen. Dateien dürfen höchstens 300MB groß sein, Videosegmente müssen innerhalb der Quelldauer liegen. Bei Speichermangel wende dich an einen Administrator.",
