    "TEST 연결 주문": "Angebundene TEST-Bestellung",
    "현재 플랜의 판매 중 에셋 한도에 도달했습니다.": "Das Limit aktiver Assets dieses Tarifs ist erreicht.",
    "플랜 기간이 종료되었습니다. 구독 상태를 확인해주세요.": "Die Tariflaufzeit ist beendet. Prüfe deinen Abo-Status.",
    "보호 검수본을 만들지 못했습니다. 원본은 보존됩니다.": "Geschützte Prüfkopien konnten nicht erstellt werden. Originale bleiben erhalten.",
    "이 형식은 전체 보호 검수를 자동 생성할 수 없습니다.": "Für dieses Format kann keine vollständige geschützte Prüfkopie automatisch erstellt werden.",
