    "선택한 상품 유지 후 FREE로 전환": "Ausgewähltes Asset behalten und zu FREE wechseln",
    "주요 화면과 안내를 선택한 언어로 볼 수 있습니다. 계약·환불정책 번역은 참고용이며 한국어 원문을 함께 확인해주세요. 창작자 콘텐츠는 원문으로 표시됩니다.": "Hauptseiten und Anleitungen sind in deiner Sprache verfügbar. Vertrags- und Erstattungsübersetzungen dienen als Referenz; lies auch das koreanische Original. Kreativinhalte bleiben in ihrer Originalsprache.",
    "추가 작업 없음": "Keine Zusatzarbeiten",
